"""Prepare an isolated Python runtime for public-repository test execution."""

import hashlib
import logging
import os
import re
import shutil
import subprocess
import sys
import venv
from pathlib import Path


class TestEnvironmentError(RuntimeError):
    """A target repository's test environment could not be prepared safely."""


logger = logging.getLogger(__name__)


_ENV_KEY = re.compile(r"^[A-Za-z_][A-Za-z0-9_]*$")
_IGNORED_REQUIREMENT_PREFIXES = ("-", ".", "/", "\\")


def _requirements(root: Path) -> tuple[Path | None, str]:
    manifest = root / "requirements.txt"
    if not manifest.is_file():
        return None, ""
    try:
        text = manifest.read_text(errors="strict")
    except (OSError, UnicodeError) as exc:
        raise TestEnvironmentError("Could not read requirements.txt.") from exc
    if len(text) > 64_000:
        raise TestEnvironmentError("requirements.txt exceeds the 64 KB setup limit.")
    for line in text.splitlines():
        requirement = line.split("#", 1)[0].strip()
        if not requirement:
            continue
        if (
            requirement.startswith(_IGNORED_REQUIREMENT_PREFIXES)
            or "://" in requirement
            or " @ " in requirement
        ):
            raise TestEnvironmentError(
                "requirements.txt contains a direct URL, local path, or pip option; automatic setup skipped."
            )
    return manifest, hashlib.sha256(text.encode()).hexdigest()


def _python_path(environment_root: Path) -> Path:
    if os.name == "nt":
        return environment_root / "Scripts" / "python.exe"
    return environment_root / "bin" / "python"


def _subprocess_environment(
    home: Path,
    python_path: Path | None = None,
    *,
    allow_network: bool = False,
) -> dict[str, str]:
    path_parts = []
    if python_path is not None:
        path_parts.append(str(python_path.parent))
    path_parts.append(os.environ.get("PATH", os.defpath))
    env = {
        "PATH": os.pathsep.join(path_parts),
        "HOME": str(home),
        "TMPDIR": str(home),
        "PYTHONDONTWRITEBYTECODE": "1",
        "LANG": "C.UTF-8",
    }
    if "SYSTEMROOT" in os.environ:
        env["SYSTEMROOT"] = os.environ["SYSTEMROOT"]
    if allow_network:
        for key in ("HTTP_PROXY", "HTTPS_PROXY", "ALL_PROXY", "NO_PROXY", "SSL_CERT_FILE", "SSL_CERT_DIR"):
            if key in os.environ:
                env[key] = os.environ[key]
    return env


def _example_settings(root: Path) -> dict[str, str]:
    """Read names only from a checked-in example; never load real .env values."""
    example = next(
        (root / name for name in (".env.example", ".env.sample", ".env.template") if (root / name).is_file()),
        None,
    )
    if example is None:
        return {}
    try:
        lines = example.read_text(errors="replace").splitlines()[:500]
    except OSError:
        return {}

    env: dict[str, str] = {}
    for line in lines:
        stripped = line.strip()
        if not stripped or stripped.startswith("#"):
            continue
        key, separator, _ = stripped.partition("=")
        key = key.removeprefix("export ").strip()
        if not separator or not _ENV_KEY.fullmatch(key):
            continue
        upper_key = key.upper()
        if upper_key == "DATABASE_URL":
            env[key] = "REDACTED"
        elif upper_key.endswith(("_URL", "_URI")):
            env[key] = "http://127.0.0.1"
        elif any(token in upper_key for token in ("SECRET", "_KEY", "TOKEN", "PASSWORD")):
            env[key] = "testgap-placeholder-not-a-real-secret"
        elif upper_key.endswith("_PORT"):
            env[key] = "5432"
        else:
            env[key] = "testgap-placeholder"
    return env


def prepare_test_environment(
    root: Path,
    *,
    timeout_seconds: int,
) -> tuple[Path, dict[str, str], dict[str, str]]:
    """Install safe, manifest-declared dependencies in a disposable per-run venv."""
    manifest, fingerprint = _requirements(root)
    env_root = root.parent / ".testgap-venv"
    runner = _python_path(env_root)
    marker = env_root / ".testgap-requirements-sha256"
    if manifest is None:
        return Path(sys.executable), fallback_test_environment(root, root.parent), {
            "status": "no_requirements_manifest"
        }

    try:
        if not runner.is_file() or not marker.is_file() or marker.read_text() != fingerprint:
            if env_root.exists():
                shutil.rmtree(env_root)
            # Clone workspaces may be mounted `noexec` by hosted runtimes.
            # On POSIX, symlink the host interpreter instead of copying it
            # into that mount; otherwise ensurepip cannot launch the venv Python.
            venv.EnvBuilder(
                with_pip=True,
                clear=True,
                symlinks=(os.name != "nt"),
            ).create(env_root)
            setup_timeout = max(90, min(timeout_seconds, 300))
            install = subprocess.run(
                [
                    str(runner), "-m", "pip", "install", "--disable-pip-version-check",
                    "--no-input", "--no-cache-dir", "--only-binary=:all:",
                    "-r", str(manifest), "pytest", "pytest-asyncio", "coverage",
                ],
                cwd=root,
                capture_output=True,
                text=True,
                timeout=setup_timeout,
                check=False,
                shell=False,
                env=_subprocess_environment(env_root, runner, allow_network=True),
            )
            if install.returncode != 0:
                raise TestEnvironmentError(
                    f"Could not install the repository's test dependencies (pip exit code {install.returncode})."
                )
            marker.write_text(fingerprint)
    except subprocess.TimeoutExpired as exc:
        shutil.rmtree(env_root, ignore_errors=True)
        raise TestEnvironmentError("Installing repository test dependencies exceeded the setup time limit.") from exc
    except (OSError, subprocess.CalledProcessError) as exc:
        shutil.rmtree(env_root, ignore_errors=True)
        logger.exception("Could not create the disposable Python test environment")
        raise TestEnvironmentError("Could not create the disposable Python test environment.") from exc

    child_env = _subprocess_environment(env_root, runner)
    child_env["PYTHONPATH"] = os.pathsep.join((str(root), str(root / "src")))
    child_env.update(_example_settings(root))
    return runner, child_env, {"status": "ready", "dependency_manifest": "requirements.txt"}


def fallback_test_environment(root: Path, home: Path) -> dict[str, str]:
    """Build a scrubbed process environment with local-only example settings."""
    env = _subprocess_environment(home)
    env["PYTHONPATH"] = os.pathsep.join((str(root), str(root / "src")))
    env.update(_example_settings(root))
    return env
import ast
import json
import os
import shutil
import subprocess
import sys
import tempfile
from pathlib import Path

from agent.test_environment import (
    TestEnvironmentError,
    fallback_test_environment,
    prepare_test_environment,
)
from agent.state import TestGapState, report_progress


def _static_python_files(root: Path, ignored: set[str]) -> tuple[dict[str, dict], int]:
    """Return AST statement lines as uncovered candidates when pytest has no tests."""
    files: dict[str, dict] = {}
    parse_failures = 0
    for source_path in root.rglob("*.py"):
        relative = source_path.relative_to(root)
        if any(part in ignored or part in {"tests", "test"} for part in relative.parts):
            continue
        if source_path.is_symlink() or source_path.name.startswith("test_"):
            continue
        try:
            tree = ast.parse(source_path.read_text(errors="replace"), filename=str(source_path))
        except (OSError, SyntaxError, UnicodeError):
            parse_failures += 1
            continue
        statement_lines = sorted({
            node.lineno
            for node in ast.walk(tree)
            if isinstance(node, ast.stmt) and hasattr(node, "lineno")
        })
        if statement_lines:
            files[str(source_path)] = {
                "executed_lines": [],
                "missing_lines": statement_lines,
                "missing_branches": [],
            }
    return files, parse_failures


def _is_environment_collection_failure(output: str) -> bool:
    """Identify collection failures caused by missing project setup, not test assertions."""
    return (
        "ModuleNotFoundError: No module named" in output
        or ("ValidationError" in output and "Field required" in output)
    )


def run_baseline(state: TestGapState) -> dict:
    report_progress(
        state,
        step="baseline",
        message="Preparing the isolated test environment and running the existing pytest suite.",
    )
    root = Path(state["project_path"]).resolve(strict=True)
    ignored = {
        ".git", ".venv", "venv", "node_modules", "__pycache__", ".pytest_cache",
        ".aws", ".ssh", ".config", ".coverage",
    }
    with tempfile.TemporaryDirectory(prefix="testgap-baseline-") as temp_dir:
        workspace = Path(temp_dir) / root.name

        def ignore_entries(directory: str, names: list[str]) -> set[str]:
            return {
                name
                for name in names
                if name in ignored
                or name == ".env"
                or name.startswith(".env.")
                or (Path(directory) / name).is_symlink()
            }

        shutil.copytree(root, workspace, ignore=ignore_entries, symlinks=False)
        coverage_file = Path(temp_dir) / "coverage.json"
        stdout_path = Path(temp_dir) / "pytest.stdout"
        stderr_path = Path(temp_dir) / "pytest.stderr"
        test_environment = {"status": "not_prepared"}
        setup_warning = None
        runner = Path(sys.executable)
        if state.get("repository_url"):
            try:
                runner, child_env, test_environment = prepare_test_environment(
                    root,
                    timeout_seconds=state.get("run_timeout_seconds", 90),
                )
            except TestEnvironmentError as exc:
                setup_warning = str(exc)
                test_environment = {"status": "failed", "reason": setup_warning}
                child_env = fallback_test_environment(root, Path(temp_dir))
        else:
            child_env = {
                "PATH": os.environ.get("PATH", ""),
                "HOME": temp_dir,
                "PYTHONPATH": os.pathsep.join((str(workspace), str(workspace / "src"))),
                "PYTHONDONTWRITEBYTECODE": "1",
            }
            if "SYSTEMROOT" in os.environ:
                child_env["SYSTEMROOT"] = os.environ["SYSTEMROOT"]
        child_env["PYTHONPATH"] = os.pathsep.join((str(workspace), str(workspace / "src")))
        with stdout_path.open("wb") as stdout_file, stderr_path.open("wb") as stderr_file:
            result = subprocess.run(
                [
                    str(runner), "-m", "coverage", "run", "--branch", "-m", "pytest",
                    "-q", "-p", "no:cacheprovider",
                ],
                cwd=workspace,
                stdout=stdout_file,
                stderr=stderr_file,
                timeout=state.get("run_timeout_seconds", 90),
                check=False,
                shell=False,
                env=child_env,
            )
        summary: dict = {
            **state.get("baseline_summary", {}),
            "command": "python -m coverage run --branch -m pytest -q",
            "test_environment": test_environment,
            "exit_code": result.returncode,
            "stdout": stdout_path.read_bytes()[-8000:].decode(errors="replace"),
            "stderr": stderr_path.read_bytes()[-8000:].decode(errors="replace"),
        }
        warning = None
        coverage_pct = None
        baseline_status = "passed"
        if result.returncode == 0:
            report = subprocess.run(
                [str(runner), "-m", "coverage", "json", "-o", str(coverage_file)],
                cwd=workspace,
                capture_output=True,
                text=True,
                timeout=state.get("run_timeout_seconds", 90),
                check=False,
                shell=False,
                env=child_env,
            )
            if report.returncode == 0 and coverage_file.exists():
                data = json.loads(coverage_file.read_text())
                totals = data.get("totals", {})
                coverage_pct = totals.get("percent_covered")
                summary["coverage_totals"] = totals
                summary["files"] = data.get("files", {})
            else:
                warning = "Tests passed, but coverage.py did not produce a JSON report."
        elif result.returncode == 5:
            files, parse_failures = _static_python_files(workspace, ignored)
            summary["files"] = files
            summary["baseline_mode"] = "bootstrap" if files else "no_python_source"
            summary["parse_failures"] = parse_failures
            summary["coverage_totals"] = {
                "covered_lines": 0,
                "num_statements": sum(len(file_data["missing_lines"]) for file_data in files.values()),
                "percent_covered": 0.0 if files else None,
            }
            if files:
                coverage_pct = 0.0
                baseline_status = "bootstrap"
                warning = (
                    "pytest found no tests; treating discovered Python statements as uncovered "
                    "and continuing in bootstrap mode."
                )
            else:
                baseline_status = "no_python_source"
                warning = "pytest found no tests and no testable Python source files were found."
        else:
            combined_output = summary["stdout"] + "\n" + summary["stderr"]
            if setup_warning or _is_environment_collection_failure(combined_output):
                files, parse_failures = _static_python_files(workspace, ignored)
                if files:
                    summary["files"] = files
                    summary["baseline_mode"] = "environment_bootstrap"
                    summary["parse_failures"] = parse_failures
                    summary["coverage_totals"] = {
                        "covered_lines": None,
                        "num_statements": sum(len(file_data["missing_lines"]) for file_data in files.values()),
                        "percent_covered": None,
                    }
                    baseline_status = "bootstrap"
                    warning = (
                        "Pytest collection could not start because project dependencies or required settings "
                        "are missing in the scanner environment. Coverage is unavailable; continuing with "
                        "AST-based candidates. Generated tests may remain unverified until setup is provided."
                    )
                    if setup_warning:
                        warning = f"{setup_warning} Coverage is unavailable; continuing with AST-based candidates."
                else:
                    baseline_status = "failed"
                    warning = (
                        "Pytest collection failed because project setup is missing, and no Python source "
                        "files were available for AST-based fallback."
                    )
            else:
                baseline_status = "failed"
                warning = "The existing baseline suite failed; generation is blocked until the baseline is understood."
        summary["baseline_status"] = baseline_status

    events = [
        {
            "type": "step.completed",
            "step": "baseline",
            "status": "success" if baseline_status == "passed" else "warning",
            "message": (
                f"Baseline passed; line coverage is {coverage_pct:.1f}%."
                if coverage_pct is not None and result.returncode == 0
                else warning or "Baseline command completed."
            ),
            "data": {"exit_code": result.returncode, "coverage_pct": coverage_pct},
        }
    ]
    return {
        "baseline_exit_code": result.returncode,
        "baseline_status": baseline_status,
        "baseline_summary": summary,
        "coverage_before_pct": coverage_pct,
        "warnings": [warning] if warning else [],
        "events": events,
    }

